package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Stamps the deterministic {@code householdId} onto a newly built owner. The id is a pure function
 * of the owner's last name and postcode (see {@link OwnerHousehold#id}), so it is always assigned -
 * owners with the same last name and postcode converge on the same value automatically, with no
 * lookup or coordination. Runs after {@link BuildOwner}, so the built owner (with its normalized
 * fields) is available to stamp, and before the household-duplicate check and identity check, which
 * both key off the finalized id.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(OwnerHousehold.id(owner.getLastName(), owner.getPostcode()));
    }
}
===== CheckOwnerHouseholdUnique.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.HouseholdDuplicateException;

/**
 * The household-duplicate block. The household is now keyed on the computed {@code householdId}
 * (last name + postcode), so a request that shares an existing owner's household is, by default, a
 * duplicate and is rejected with 409. Declaring {@code sharesHousehold: true} bypasses this block -
 * the owner is then created as a declared household member (and is not flagged as a suspected
 * duplicate later by {@link AssignPossibleDuplicate}).
 *
 * <p>Runs after {@link AssignHousehold} finalizes the id and before {@link CheckOwnerIdentityUnique}.
 * The two checks are distinct: this one is bypassed by {@code sharesHousehold}, whereas the identity
 * check (the full {@code telephone|email|householdId} key) never is - so a full duplicate that also
 * declares {@code sharesHousehold} still collides on its identity key.
 */
public class CheckOwnerHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
            throws HouseholdDuplicateException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // declared household member - bypass the duplicate block
        }
        String householdId = owner.getHouseholdId();
        for (Owner existing : ownerRepository.findAll()) {
            // The owner being created is not yet persisted, so findAll() returns only other owners.
            // A soft-deleted owner is ignored, so its household never blocks a new create.
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue;
            }
            if (householdId.equals(existing.getHouseholdId())) {
                throw new HouseholdDuplicateException(householdId);
            }
        }
    }
}
===== CheckOwnerIdentityUnique.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
import org.springframework.samples.petclinic.util.OwnerIdentity;

/**
 * The single duplicate-detection step for the create-owner pipeline: it rejects a request whose
 * derived {@code identityKey} (normalizedTelephone|email|householdId) exactly equals an existing
 * owner's. This one check subsumes the former separate telephone, email and household checks.
 *
 * <p>Runs after {@link BuildOwner} and {@link AssignHousehold}, so the new owner's telephone and
 * email are normalized and its household id is finalized (including any back-fill of existing
 * members) - the key is therefore compared against every other owner's finalized key. Because the
 * telephone is part of the key, two household members with different telephones have different keys
 * and both are allowed; only an exact whole-key match is a duplicate. Throws
 * {@link DuplicateIdentityException} (handled as 409) on a collision.
 */
public class CheckOwnerIdentityUnique {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = OwnerIdentity.key(owner);
        for (Owner existing : ownerRepository.findAll()) {
            // The owner being created is not yet persisted, so findAll() returns only other owners.
            // A soft-deleted owner is ignored, so its key never blocks a new create.
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue;
            }
            if (identityKey.equals(OwnerIdentity.key(existing))) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
